using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using WaveHarmonic.Crest;
namespace CityForge.Editor {
[InitializeOnLoad] public static class LakeShoreRefinement {
const string Root="Assets/CityForge/Art/Environment/CrestVisualLab/",Work="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/work/",Out="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/outputs/";
static LakeShoreRefinement(){EditorApplication.update+=Tick;}
static void Tick(){if(EditorApplication.isCompiling)return;try{if(File.Exists(Work+"lake-refine")&&!EditorApplication.isPlaying){File.Delete(Work+"lake-refine");Run();}if(File.Exists(Work+"lake-polish")){File.Delete(Work+"lake-polish");var w=UnityEngine.Object.FindFirstObjectByType<WaterRenderer>();w.Surface.Material.SetFloat("_Crest_Specular",.04f);w.Surface.Material.SetFloat("_Crest_Smoothness",.98f);w.Surface.Material.SetFloat("_Crest_SmoothnessFar",.98f);w.Surface.Material.DisableKeyword("_SPECULARHIGHLIGHTS_OFF");EditorUtility.SetDirty(w.Surface.Material);AssetDatabase.SaveAssets();}if(File.Exists(Work+"lake-capture")){File.Delete(Work+"lake-capture");Capture();}}catch(Exception e){Debug.LogException(e);}}
[MenuItem("CityForge/Crest Visual Lab/4 - Shoreline Refinement")]
static void Run(){var scene=EditorSceneManager.OpenScene(Root+"LakeWaves.unity");var ground=GameObject.Find("Ground with meadow, canopy litter and dirt masks").GetComponent<Renderer>();var m=new Material(ground.sharedMaterial);m.shader=Shader.Find("CityForge/Lake Shore Ground");Save(m,"ShoreGround");ground.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(Root+"ShoreGround.mat");
var w=UnityEngine.Object.FindFirstObjectByType<WaterRenderer>();var water=new Material(w.Surface.Material);Save(water,"ShoreFreshwater");var so=new SerializedObject(w);so.FindProperty("_Surface._Material").objectReferenceValue=AssetDatabase.LoadAssetAtPath<Material>(Root+"ShoreFreshwater.mat");so.ApplyModifiedPropertiesWithoutUndo();
var reeds=GameObject.Find("MapMagic pond shoreline reeds and stones");int removed=0;foreach(Transform t in reeds.transform.Cast<Transform>().ToArray()){if(t.name.StartsWith("Stone"))continue;var p=t.position;float a=Mathf.Atan2((p.z-130)/30,(p.x-133)/40);if(!(a>-.3f&&a<.25f||a>1.15f&&a<1.7f||a<-1.8f&&a>-2.25f)){UnityEngine.Object.DestroyImmediate(t.gameObject);removed++;}}
var stones=new GameObject("Shallow submerged stone groups");var stoneMat=new Material(Shader.Find("Universal Render Pipeline/Lit"));stoneMat.SetColor("_BaseColor",new Color(.25f,.24f,.20f));stoneMat.SetFloat("_Smoothness",.08f);Save(stoneMat,"BedStones");var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);var rng=new System.Random(6512);for(int i=0;i<42;i++){float a=new[]{-.8f,-2.6f,.65f,2.15f}[i%4]+((float)rng.NextDouble()-.5f)*.28f;float r=.87f+(float)rng.NextDouble()*.16f;float edge=1+.065f*Mathf.Sin(a*3+.5f)+.04f*Mathf.Sin(a*7-1)+.018f*Mathf.Sin(a*11);float x=133+40*Mathf.Cos(a)*r*edge,z=130+30*Mathf.Sin(a)*r*edge;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CityForge/Art/Environment/ObjectsWoodlandStudy/Stone"+(i%3+1)+".prefab");var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab);go.transform.SetParent(stones.transform);go.transform.position=new Vector3(x,terrain.SampleHeight(new Vector3(x,0,z))-.10f,z);go.transform.rotation=Quaternion.Euler(0,(float)rng.NextDouble()*360,0);go.transform.localScale=Vector3.one*(.16f+(float)rng.NextDouble()*.22f);go.layer=30;foreach(var ren in go.GetComponentsInChildren<Renderer>())ren.sharedMaterials=ren.sharedMaterials.Select(_=>AssetDatabase.LoadAssetAtPath<Material>(Root+"BedStones.mat")).ToArray();}
AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"LakeShore.unity");Debug.Log("LAKE SHORE READY removed evenly distributed reeds="+removed);}
static void Save(Material m,string name){var path=Root+name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);}else AssetDatabase.CreateAsset(m,path);}
static void Capture(){var c=GameObject.Find("Meadow presentation camera").GetComponent<Camera>();var method=typeof(CrestVisualLab).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static);bool original=c.orthographic;float fov=c.fieldOfView;foreach(bool ortho in new[]{false,true}){c.orthographic=ortho;c.fieldOfView=40;c.ResetProjectionMatrix();string name="LakeShore"+(ortho?"_Orthographic":"_Perspective");method.Invoke(null,new object[]{c,name});File.Copy("/Users/joelinstrum/Documents/Codex/2026-10-08/tre/outputs/"+name+".png",Out+name+".png",true);}c.orthographic=original;c.fieldOfView=fov;c.ResetProjectionMatrix();Debug.Log("LAKE SHORE CAPTURE COMPLETE");}
}}
